import hou
import houdini_mcp_plugin.startup as startup

try:
    startup.start()
except Exception as exc:
    hou.ui.displayMessage(
        f'Could not start the Houdini MCP plugin:\n\n{exc}',
        severity=hou.severityType.Error,
        title='Houdini MCP',
    )
else:
    hou.ui.setStatusMessage(f'Houdini MCP running on port {startup.get_port()}')
